import { BidictRuntimeError } from './errors.mjs';
import { writeStderr } from './io.mjs';

function formatBidictTraceback(error) {
  return [
    'Traceback (most recent call last):',
    `  File "test8.py", line ${error.pythonLine}, in <module>`,
    '  File "bidict/_bidict.py", line 80, in __setitem__',
