    `bidict.${error.name}: ${error.pythonMessage}`,
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test8' due to unhandled exception!`,
  ].join('\n');
}

export function runWithPythonStyleRuntime(main) {
  try {
    main();
  } catch (error) {
    if (error instanceof ScriptExitSignal) {
