  { id: 'k1', name: '--k1', metavar: 'K1', type: 'string' },
  { id: 'v1', name: '--v1', metavar: 'V1', type: 'int' },
  { id: 'k2', name: '--k2', metavar: 'K2', type: 'string' },
  { id: 'v2', name: '--v2', metavar: 'V2', type: 'int' },
  { id: 'k3', name: '--k3', metavar: 'K3', type: 'string' },
  { id: 'v3', name: '--v3', metavar: 'V3', type: 'int' },
]);

const DEFINITION_BY_NAME = Object.create(null);

for (const definition of ARGUMENT_DEFINITIONS) {
  DEFINITION_BY_NAME[definition.name] = definition;
}

const LONG_OPTIONS = Object.freeze(['--help', ...ARGUMENT_DEFINITIONS.map((definition) => definition.name)]);
const INTEGER_PATTERN = /^[+-]?\d(?:_?\d)*$/;

export function formatUsage(progName) {
  return `usage: ${progName} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3`;
}

export function formatHelp(progName) {
  return `${formatUsage(progName)}

options:
  -h, --help  show this help message and exit
  --k1 K1
  --v1 V1
  --k2 K2
  --v2 V2
  --k3 K3
  --v3 V3`;
