  if (LONG_OPTIONS.includes(token)) {
    return { kind: 'match', name: token };
  }

  const matches = LONG_OPTIONS.filter((option) => option.startsWith(token));

  if (matches.length === 1) {
    return { kind: 'match', name: matches[0] };
  }

  if (matches.length > 1) {
    return { kind: 'ambiguous', matches };
  }

  return { kind: 'unknown' };
}

