  if (!INTEGER_PATTERN.test(rawValue)) {
    return null;
  }

  const sign = rawValue.startsWith('-') ? -1n : 1n;
  const unsignedDigits = rawValue.replace(/^[+-]/, '').replace(/_/g, '');
