    const token = tokens[index];

    if (token === '-h') {
      emitHelp(progName);
    }

    if (token === '--') {
      leftovers.push(...tokens.slice(index + 1));
      break;
    }

    if (token.startsWith('--') && token.length > 2) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const resolution = resolveLongOption(optionToken);

      if (resolution.kind === 'ambiguous') {
