export function pythonStringRepr(value) {
  const stringValue = String(value);
  const quote = chooseQuote(stringValue);
  let result = quote;

  for (const character of stringValue) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      result += '\\\\';
      continue;
    }

    if (character === quote) {
      result += `\\${quote}`;
      continue;
    }

    if (character === '\t') {
      result += '\\t';
      continue;
    }

    if (character === '\n') {
      result += '\\n';
      continue;
    }

    if (character === '\r') {
      result += '\\r';
      continue;
    }

    if (isPrintable(codePoint)) {
      result += character;
      continue;
    }

    result += hexEscape(codePoint);
  }

  result += quote;
  return result;
}

